package io.github.jimbozoomer.jugcraft.client;

import java.util.Map;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.util.Mth;

/** Supplied MutantZombieModel arithmetic; generated by tools/recover_mutant_poses.py. */
final class RecoveredMutantPoses {
    static void apply(String model, RecoveredWildlifeRenderer.State state, Map<String, ModelPart> parts) {
        if (!model.equals("recovered/mutants_mutantzombiemodel") || state.actionTime < 0) return;
        if (state.action.equals("slam_ground")) animateMelee(state,parts);
        if (state.action.equals("roar")) animateRoar(state,parts);
    }
    private static void addRotation(ModelPart part,float x,float y,float z){part.xRot+=x;part.yRot+=y;part.zRot+=z;}
    private static void animateMelee(RecoveredWildlifeRenderer.State state, Map<String, ModelPart> parts) {

        parts.get("right_arm").zRot = 0.0f;
        parts.get("left_arm").zRot = 0.0f;
        if (state.actionTime < 8.0f) {
            float progress = state.actionTime / 8.0f;
            float swingAmount = -Mth.sin((double)(progress * (float)Math.PI / 2.0f));
            float swayAmount = Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot += swingAmount * 0.2f;
            parts.get("chest").xRot += swingAmount * 0.2f;
            parts.get("right_arm").xRot += swingAmount * 2.3f;
            parts.get("right_arm").zRot += swayAmount * (float)Math.PI / 8.0f;
            parts.get("left_arm").xRot += swingAmount * 2.3f;
            parts.get("left_arm").zRot -= swayAmount * (float)Math.PI / 8.0f;
            parts.get("right_arm_lower").xRot += swingAmount * 0.8f;
            parts.get("left_arm_lower").xRot += swingAmount * 0.8f;
        } else if (state.actionTime < 12.0f) {
            float progress = (state.actionTime - 8.0f) / 4.0f;
            float swingAmount = -Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            float swayAmount = Mth.sin((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot += swingAmount * 0.9f + 0.7f;
            parts.get("chest").xRot += swingAmount * 0.9f + 0.7f;
            parts.get("right_arm").xRot += swingAmount * 0.2f - 2.1f;
            parts.get("right_arm").zRot += swayAmount * 0.3f;
            parts.get("left_arm").xRot += swingAmount * 0.2f - 2.1f;
            parts.get("left_arm").zRot -= swayAmount * 0.3f;
            parts.get("right_arm_lower").xRot += swingAmount + 0.2f;
            parts.get("left_arm_lower").xRot += swingAmount + 0.2f;
        } else if (state.actionTime < 16.0f) {
            parts.get("waist").xRot += 0.7f;
            parts.get("chest").xRot += 0.7f;
            parts.get("right_arm").xRot -= 2.1f;
            parts.get("right_arm").zRot += 0.3f;
            parts.get("left_arm").xRot -= 2.1f;
            parts.get("left_arm").zRot -= 0.3f;
            parts.get("right_arm_lower").xRot += 0.2f;
            parts.get("left_arm_lower").xRot += 0.2f;
        } else if (state.actionTime < 24.0f) {
            float progress = (state.actionTime - 16.0f) / 8.0f;
            float swingAmount = Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot += swingAmount * 0.7f;
            parts.get("chest").xRot += swingAmount * 0.7f;
            parts.get("right_arm").xRot -= swingAmount * 2.1f;
            parts.get("right_arm").zRot += swingAmount * -0.09269908f + 0.3926991f;
            parts.get("left_arm").xRot -= swingAmount * 2.1f;
            parts.get("left_arm").zRot -= swingAmount * -0.09269908f + 0.3926991f;
            parts.get("right_arm_lower").xRot += swingAmount * 0.2f;
            parts.get("left_arm_lower").xRot += swingAmount * 0.2f;
        } else {
            parts.get("right_arm").zRot += 0.3926991f;
            parts.get("left_arm").zRot += -0.3926991f;
        }
    
    }
    private static void animateRoar(RecoveredWildlifeRenderer.State state, Map<String, ModelPart> parts) {

        float swayAmount;
        float roarAmount;
        float progress;
        if (state.actionTime < 10.0f) {
            progress = state.actionTime / 10.0f;
            roarAmount = Mth.sin((double)(progress * (float)Math.PI / 2.0f));
            swayAmount = Mth.sin((double)(progress * (float)Math.PI * (float)Math.PI / 8.0f));
            parts.get("waist").xRot += roarAmount * 0.2f;
            parts.get("chest").xRot += roarAmount * 0.4f;
            parts.get("chest").yRot += swayAmount * 0.06f;
            parts.get("head").xRot += roarAmount * 0.8f;
            parts.get("right_arm").xRot -= roarAmount * 1.2f;
            parts.get("right_arm").zRot += roarAmount * 0.6f;
            parts.get("left_arm").xRot -= roarAmount * 1.2f;
            parts.get("left_arm").zRot -= roarAmount * 0.6f;
            parts.get("right_arm_lower").xRot -= roarAmount * 0.8f;
            parts.get("left_arm_lower").xRot -= roarAmount * 0.8f;
        } else if (state.actionTime < 15.0f) {
            progress = (state.actionTime - 10.0f) / 5.0f;
            roarAmount = Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            swayAmount = Mth.sin((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot += roarAmount * 0.39634955f - 0.19634955f;
            parts.get("chest").xRot += roarAmount * 0.6f - 0.2f;
            parts.get("head").xRot += roarAmount - 0.2f;
            parts.get("right_arm").xRot -= roarAmount * 2.2f - 1.0f;
            parts.get("right_arm").yRot += swayAmount * 0.4f;
            parts.get("right_arm").zRot += 0.6f;
            parts.get("left_arm").xRot -= roarAmount * 2.2f - 1.0f;
            parts.get("left_arm").yRot -= swayAmount * 0.4f;
            parts.get("left_arm").zRot -= 0.6f;
            parts.get("right_arm_lower").xRot -= roarAmount - 0.2f;
            parts.get("left_arm_lower").xRot -= roarAmount - 0.2f;
            parts.get("right_leg").yRot += swayAmount * 0.3f;
            parts.get("left_leg").yRot -= swayAmount * 0.3f;
        } else if (state.actionTime < 75.0f) {
            parts.get("waist").xRot -= 0.19634955f;
            parts.get("chest").xRot -= 0.2f;
            parts.get("head").xRot -= 0.2f;
            addRotation(parts.get("right_arm"), 1.0f, 0.4f, 0.6f);
            addRotation(parts.get("left_arm"), 1.0f, -0.4f, -0.6f);
            parts.get("right_arm_lower").xRot += 0.2f;
            parts.get("left_arm_lower").xRot += 0.2f;
            parts.get("right_leg").yRot += 0.3f;
            parts.get("left_leg").yRot -= 0.3f;
        } else if (state.actionTime < 90.0f) {
            progress = (state.actionTime - 75.0f) / 15.0f;
            roarAmount = Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot -= roarAmount * 0.69634956f - 0.5f;
            parts.get("chest").xRot -= roarAmount * 0.7f - 0.5f;
            parts.get("head").xRot -= roarAmount * 0.6f - 0.4f;
            addRotation(parts.get("right_arm"), roarAmount * 2.6f - 1.6f, roarAmount * 0.4f, roarAmount * 0.99269915f - 0.3926991f);
            addRotation(parts.get("left_arm"), roarAmount * 2.6f - 1.6f, -roarAmount * 0.4f, -roarAmount * 0.99269915f + 0.3926991f);
            parts.get("right_arm_lower").xRot += roarAmount * -0.6f + 0.8f;
            parts.get("left_arm_lower").xRot += roarAmount * -0.6f + 0.8f;
            parts.get("right_leg").yRot += roarAmount * 0.3f;
            parts.get("left_leg").yRot -= roarAmount * 0.3f;
        } else if (state.actionTime < 110.0f) {
            parts.get("waist").xRot += 0.5f;
            parts.get("chest").xRot += 0.5f;
            parts.get("head").xRot += 0.4f;
            addRotation(parts.get("right_arm"), -1.6f, 0.0f, -0.3926991f);
            addRotation(parts.get("left_arm"), -1.6f, 0.0f, 0.3926991f);
            parts.get("right_arm_lower").xRot += 0.8f;
            parts.get("left_arm_lower").xRot += 0.8f;
        } else {
            progress = (state.actionTime - 110.0f) / 10.0f;
            roarAmount = Mth.cos((double)(progress * (float)Math.PI / 2.0f));
            parts.get("waist").xRot += roarAmount * 0.5f;
            parts.get("chest").xRot += roarAmount * 0.5f;
            parts.get("head").xRot += roarAmount * 0.4f;
            addRotation(parts.get("right_arm"), roarAmount * -1.6f, 0.0f, roarAmount * (float)(-Math.PI) / 8.0f);
            addRotation(parts.get("left_arm"), roarAmount * -1.6f, 0.0f, roarAmount * (float)Math.PI / 8.0f);
            parts.get("right_arm_lower").xRot += roarAmount * 0.8f;
            parts.get("left_arm_lower").xRot += roarAmount * 0.8f;
        }
        if (state.actionTime >= 10.0f && state.actionTime < 75.0f) {
            progress = (state.actionTime - 10.0f) / 65.0f;
            roarAmount = Mth.sin((double)(progress * (float)Math.PI * 8.0f));
            swayAmount = Mth.sin((double)(progress * (float)Math.PI * 8.0f + 0.7853982f));
            parts.get("head").yRot += roarAmount * 0.5f - swayAmount * 0.2f;
            parts.get("head").zRot -= roarAmount * 0.5f;
            parts.get("chest").yRot += swayAmount * 0.06f;
        }
    
    }
}
